    @Test("DAG-029 reverse a chain one edge at a time")
    func dag029() throws {
        // DirectedPseudograph; V [0, 1, 2, 3]; E [] / insert(edge: 3→2) / insert(edge: 2→1) / insert(edge: 1→0)
        var graph = try #require(DirectedAcyclicGraph<DirectedPseudograph<Int>>(vertices: [0, 1, 2, 3], edges: [] as [DirectedEdge<Int>]))
        #expect(graph.insert(edge: DirectedEdge(from: 3, to: 2)) == 0)
        // After insert(edge: 3→2).
        #expect(Array(graph.topologicalOrder) == [0, 1, 3, 2])
        #expect(Array(graph.vertices) == [0, 1, 2, 3])
        #expect(Array(graph.edges.indices) == [0])
        #expect(Array(graph.edges) == [DirectedEdge(from: 3, to: 2)])
        #expect(graph.insert(edge: DirectedEdge(from: 2, to: 1)) == 1)
        // After insert(edge: 2→1).
        #expect(Array(graph.topologicalOrder) == [0, 3, 2, 1])
        #expect(Array(graph.vertices) == [0, 1, 2, 3])
        #expect(Array(graph.edges.indices) == [0, 1])
        #expect(Array(graph.edges) == [DirectedEdge(from: 3, to: 2), DirectedEdge(from: 2, to: 1)])
        #expect(graph.insert(edge: DirectedEdge(from: 1, to: 0)) == 2)
        // Final state.
        #expect(Array(graph.topologicalOrder) == [3, 2, 1, 0])
        #expect(Array(graph.vertices) == [0, 1, 2, 3])
        #expect(Array(graph.edges.indices) == [0, 1, 2])
